56: const state={turn:1,maxTurns:5,energy:2,maxEnergy:2,hand:[],player:[[],[],[]],enemy:[[],[],[]],selectedCard:null,selectedLane:null,over:false,lock:false};
57: let toastTimer;
58: const $=s=>document.querySelector(s);
59: function shuffled(){return [...cardPool].sort(()=>Math.random()-.5)}
60: function draw(){const deck=shuffled();state.hand=deck.slice(0,5);state.deck=deck.slice(5)}
61: function score(units){return units.reduce((sum,c)=>sum+c.power,0)}
62: function laneTotals(i){return {you:score(state.player[i]),foe:score(state.enemy[i])}}
63: function render(){
64:  $('#roundNumber').textContent=String(state.turn).padStart(2,'0');
65:  $('#arena').innerHTML=habitats.map((h,i)=>{const s=laneTotals(i),lead=s.you>s.foe?'you':s.foe>s.you?'foe':'tie';return `<button class="lane ${state.selectedLane===i?'selected':''} ${s.foe>s.you?'enemy-lead':''}" data-lane="${i}" aria-label="${h.name}, your power ${s.you}, rival power ${s.foe}"><div class="lane-head"><span class="lane-title">${h.name}</span><span class="lane-icon">${h.icon}</span></div><span class="lane-score-row">YOU / RIVAL</span><span class="lane-score">${s.you}<small style="font:500 10px var(--sans);color:#829078"> / ${s.foe}</small></span><div class="lane-art"><span>${h.art}</span></div><div class="unit-stack">${state.player[i].map(c=>`<span class="unit" title="${c.name}">${c.emoji}</span>`).join('')}${state.enemy[i].map(c=>`<span class="unit foe" title="Rival ${c.name}">${c.emoji}</span>`).join('')}</div></button>`}).join('');
66:  $('#energyPips').innerHTML=Array.from({length:state.maxEnergy},(_,i)=>`<span class="pip ${i<state.energy?'on':''}"></span>`).join('');$('#energyText').textContent=`${state.energy} / ${state.maxEnergy}`;
67:  $('#handCount').textContent=`${state.hand.length} card${state.hand.length===1?'':'s'}`;
68:  $('#hand').innerHTML=state.hand.map((c,i)=>`<button class="card ${state.selectedCard===i?'selected':''}" data-card="${i}" style="--accent:${c.color}" ${c.cost>state.energy||state.lock||state.over?'disabled':''} aria-label="${c.name}, ${c.power} power, costs ${c.cost} energy"><div class="card-top"><span class="faction">${c.faction}</span><span class="cost">${c.cost}</span></div><div class="card-art">${c.emoji}</div><div class="card-name">${c.name}</div><div class="card-desc">${c.desc}</div><div class="card-bottom"><span class="card-type">${c.type}</span><span class="power">${c.power} <small style="font:700 7px var(--sans)">POW</small></span></div></button>`).join('');
69:  const status=$('#turnStatus');status.innerHTML=state.over?'<strong>Clash complete.</strong> The wild remembers.':state.lock?'<strong>Rival is making a move…</strong>':`<strong>Your move.</strong> ${state.selectedCard!==null?'Now choose a habitat.':'Choose a creature you can afford.'}`;
70:  $('#selectionHelp').innerHTML=state.selectedCard===null?'Choose any card you can afford to begin.':`<b>${state.hand[state.selectedCard]?.name||'Creature'}</b> picked · tap a habitat`;
71:  $('#playBtn').disabled=state.selectedCard===null||state.selectedLane===null||state.lock||state.over;
72:  $('#newGameBtn').disabled=state.lock;
73: }
74: function showToast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1900)}
75: function applyCardEffect(card,lane,side){const own=side==='player'?state.player:state.enemy,other=side==='player'?state.enemy:state.player;
76:  if(card.bonus==='fern'&&lane===0)card.power+=2;if(card.bonus==='bay'&&lane===2)card.power+=1;
77:  if(card.effect==='scorch'&&other[lane].length){const victim=other[lane].reduce((a,b)=>a.power<b.power?a:b);victim.power=Math.max(1,victim.power-2)}
78:  if(card.effect==='rally')own[lane].forEach(c=>c.power++);
79:  if(card.effect==='pulse')own[lane].forEach(c=>c.power++);
80:  if(card.effect==='roar')other.forEach(units=>units.forEach(c=>c.power=Math.max(1,c.power-1)));
81: }
82: function deploy(){if(state.selectedCard===null||state.selectedLane===null||state.lock||state.over)return;const card=state.hand[state.selectedCard];if(!card||card.cost>state.energy)return;
83:  state.energy-=card.cost;state.hand.splice(state.selectedCard,1);applyCardEffect(card,state.selectedLane,'player');state.player[state.selectedLane].push(card);state.selectedCard=null;state.selectedLane=null;state.lock=true;render();setTimeout(enemyMove,650)}
84: function enemyMove(){if(state.over)return;let affordable=state.deck.filter(c=>c.cost<=state.energy);if(!affordable.length)affordable=state.deck;let card=affordable.sort((a,b)=>(b.power/b.cost)-(a.power/a.cost))[0];if(!card)card=cardPool[3];state.deck=state.deck.filter(c=>c!==card);
