{id:'roar',name:'Rugido Fósil',faction:'Dinosaurio',emoji:'🦣',power:3,cost:2,desc:'Un rugido feroz sacude todos los territorios rivales.',color:'#a9e85b',type:'Ancestral',effect:'roar'},
{id:'phoenix',name:'Fénix Ala de Ceniza',faction:'Dragón',emoji:'🔥',power:3,cost:2,desc:'Resurge de las cenizas con una chispa brillante.',color:'#ff9b55',type:'Renacido'}
];
const state={turn:1,maxTurns:5,energy:2,maxEnergy:2,hand:[],player:[[],[],[]],enemy:[[],[],[]],selectedCard:null,selectedLane:null,over:false,lock:false};
let toastTimer;
const $=s=>document.querySelector(s);
function shuffled(){return [...cardPool].sort(()=>Math.random()-.5)}
function draw(){const deck=shuffled();state.hand=deck.slice(0,5);state.deck=deck.slice(5)}
function score(units){return units.reduce((sum,c)=>sum+c.power,0)}
function laneTotals(i){return {you:score(state.player[i]),foe:score(state.enemy[i])}}
function render(){
 $('#roundNumber').textContent=String(state.turn).padStart(2,'0');
 $('#arena').innerHTML=habitats.map((h,i)=>{const s=laneTotals(i),lead=s.you>s.foe?'you':s.foe>s.you?'foe':'tie';return `<button class="lane ${state.selectedLane===i?'selected':''} ${s.foe>s.you?'enemy-lead':''}" data-lane="${i}" aria-label="${h.name}, your power ${s.you}, rival power ${s.foe}"><div class="lane-head"><span class="lane-title">${h.name}</span><span class="lane-icon">${h.icon}</span></div><span class="lane-score-row">YOU / RIVAL</span><span class="lane-score">${s.you}<small style="font:500 10px var(--sans);color:#829078"> / ${s.foe}</small></span><div class="lane-art"><span>${h.art}</span></div><div class="unit-stack">${state.player[i].map(c=>`<span class="unit" title="${c.name}">${c.emoji}</span>`).join('')}${state.enemy[i].map(c=>`<span class="unit foe" title="Rival ${c.name}">${c.emoji}</span>`).join('')}</div></button>`}).join('');
 $('#energyPips').innerHTML=Array.from({length:state.maxEnergy},(_,i)=>`<span class="pip ${i<state.energy?'on':''}"></span>`).join('');$('#energyText').textContent=`${state.energy} / ${state.maxEnergy}`;
 $('#handCount').textContent=`${state.hand.length} card${state.hand.length===1?'':'s'}`;
 $('#hand').innerHTML=state.hand.map((c,i)=>`<button class="card ${state.selectedCard===i?'selected':''}" data-card="${i}" style="--accent:${c.color}" ${c.cost>state.energy||state.lock||state.over?'disabled':''} aria-label="${c.name}, ${c.power} power, costs ${c.cost} energy"><div class="card-top"><span class="faction">${c.faction}</span><span class="cost">${c.cost}</span></div><div class="card-art">${c.emoji}</div><div class="card-name">${c.name}</div><div class="card-desc">${c.desc}</div><div class="card-bottom"><span class="card-type">${c.type}</span><span class="power">${c.power} <small style="font:700 7px var(--sans)">POW</small></span></div></button>`).join('');
 const status=$('#turnStatus');status.innerHTML=state.over?'<strong>Clash complete.</strong> The wild remembers.':state.lock?'<strong>Rival is making a move…</strong>':`<strong>Your move.</strong> ${state.selectedCard!==null?'Now choose a habitat.':'Choose a creature you can afford.'}`;
 $('#selectionHelp').innerHTML=state.selectedCard===null?'Choose any card you can afford to begin.':`<b>${state.hand[state.selectedCard]?.name||'Creature'}</b> picked · tap a habitat`;
