function applyCardEffect(card,lane,side){const own=side==='player'?state.player:state.enemy,other=side==='player'?state.enemy:state.player;
 if(card.bonus==='fern'&&lane===0)card.power+=2;if(card.bonus==='bay'&&lane===2)card.power+=1;
 if(card.effect==='scorch'&&other[lane].length){const victim=other[lane].reduce((a,b)=>a.power<b.power?a:b);victim.power=Math.max(1,victim.power-2)}
 if(card.effect==='rally')own[lane].forEach(c=>c.power++);
 if(card.effect==='pulse')own[lane].forEach(c=>c.power++);
 if(card.effect==='roar')other.forEach(units=>units.forEach(c=>c.power=Math.max(1,c.power-1)));
}
function deploy(){if(state.selectedCard===null||state.selectedLane===null||state.lock||state.over)return;const card=state.hand[state.selectedCard];if(!card||card.cost>state.energy)return;
 state.energy-=card.cost;state.hand.splice(state.selectedCard,1);applyCardEffect(card,state.selectedLane,'player');state.player[state.selectedLane].push(card);state.selectedCard=null;state.selectedLane=null;state.lock=true;render();setTimeout(enemyMove,650)}
function enemyMove(){if(state.over)return;let affordable=state.deck.filter(c=>c.cost<=state.energy);if(!affordable.length)affordable=state.deck;let card=affordable.sort((a,b)=>(b.power/b.cost)-(a.power/a.cost))[0];if(!card)card=cardPool[3];state.deck=state.deck.filter(c=>c!==card);
 // Rival targets the lane where a small investment can swing the most territory.
 let options=habitats.map((_,i)=>({i,ours:score(state.enemy[i]),theirs:score(state.player[i])}));options.sort((a,b)=>Math.abs(a.ours-a.theirs)-Math.abs(b.ours-b.theirs));let lane=options[0].i;
 applyCardEffect(card,lane,'enemy');state.enemy[lane].push(card);state.lock=false;state.turn++;
 if(state.turn>state.maxTurns){finishGame();return}
 state.maxEnergy=Math.min(6,state.maxEnergy+1);state.energy=state.maxEnergy;
 if(state.hand.length<5&&state.deck.length){state.hand.push(state.deck.shift())}
