 $('#roundNumber').textContent=String(Math.min(state.turn,state.maxTurns)).padStart(2,'0');refreshMeta();
 $('#arena').innerHTML=habitats.map((h,i)=>{const s=laneTotals(i);return `<button class="lane ${state.selectedLane===i?'selected':''} ${s.foe>s.you?'enemy-lead':''}" data-lane="${i}" aria-label="${h.name}: tu ataque ${s.you}, ataque rival ${s.foe}"><div class="lane-head"><span class="lane-title">${h.name}</span><span class="lane-icon">${h.icon}</span></div><span class="lane-score-row">TÚ / RIVAL · ATQ</span><span class="lane-score">${s.you}<small style="font:500 10px var(--sans);color:#829078"> / ${s.foe}</small></span><div class="lane-art"><span>${h.art}</span></div><div class="unit-stack">${state.player[i].map(c=>`<span class="unit" title="${c.name} · ATQ ${c.attack} · VIDA ${c.hpNow}/${c.hp}">${c.emoji}</span>`).join('')}${state.enemy[i].map(c=>`<span class="unit foe" title="${c.name} · ATQ ${c.attack} · VIDA ${c.hpNow}/${c.hp}">${c.emoji}</span>`).join('')}</div></button>`}).join('');
