 const status=$('#turnStatus');status.innerHTML=state.over?'<strong>Partida terminada.</strong> La naturaleza ha decidido.':state.lock?'<strong>Turno del rival…</strong>':state.actionUsed?'<strong>Acción realizada.</strong> Termina tu turno para combatir.':`<strong>Tu turno.</strong> ${state.selectedCard!==null?'Elige un hábitat para jugar.':'Juega una carta o termina el turno.'}`;
