function damageUnit(unit,amount){unit.hpNow-=amount}
function applyEffect(card,lane,side){const own=side==='player'?state.player:state.enemy,other=side==='player'?state.enemy:state.player,opponent=side==='player'?'enemyLife':'playerLife',allies=own[lane],foes=other[lane];
 switch(card.effect){case'bite':if(foes.length)damageUnit(foes.reduce((a,b)=>a.hpNow<b.hpNow?a:b),2);break;case'pack':card.attack+=allies.filter(c=>!c.support).length;break;case'fortify':card.hpNow=Math.min(card.hp,card.hpNow+2);break;case'dive':state[opponent]-=2;break;case'shell':card.hpNow=Math.min(card.hp,card.hpNow+2);card.attack++;break;case'scorch':if(foes.length)damageUnit(foes.reduce((a,b)=>a.hpNow<b.hpNow?a:b),3);break;case'storm':foes.forEach(c=>damageUnit(c,1));break;case'kin':card.attack+=allies.filter(c=>c.faction==='Fuego').length;break;case'regrow':allies.forEach(c=>c.hpNow=Math.min(c.hp,c.hpNow+2));break;case'quake':state[opponent]-=3;break;case'rally':allies.filter(c=>c!==card).forEach(c=>c.attack++);break;case'shelter':allies.filter(c=>c!==card).forEach(c=>c.hpNow=Math.min(c.hp,c.hpNow+2));break;case'pulse':allies.filter(c=>c!==card).forEach(c=>c.attack++);break;case'roar':foes.forEach(c=>c.attack=Math.max(0,c.attack-1));break;case'flare':foes.forEach(c=>damageUnit(c,1));break;case'heal':state[side==='player'?'playerLife':'enemyLife']=Math.min(30,state[side==='player'?'playerLife':'enemyLife']+5);break;case'meteor':state[opponent]-=4;break;case'roots':if(foes.length)foes.reduce((a,b)=>a.attack>b.attack?a:b).attack=Math.max(0,foes.reduce((a,b)=>a.attack>b.attack?a:b).attack-2);break;case'warcry':allies.forEach(c=>c.attack+=2);break;case'draw':drawCards(side,2);break;case'ward':allies.forEach(c=>c.hpNow=Math.min(c.hp,c.hpNow+3));break}
 state.playerLife=Math.max(0,state.playerLife);state.enemyLife=Math.max(0,state.enemyLife);cleanDead();
}
function cleanDead(){for(const side of ['player','enemy'])state[side].forEach((lane,i)=>state[side][i]=lane.filter(c=>c.hpNow>0))}
function drawCards(side,count=1){const hand=side==='player'?state.hand:state.enemyHand,deck=side==='player'?state.playerDeck:state.enemyDeck;for(let i=0;i<count&&hand.length<7&&deck.length;i++)hand.push(deck.shift())}
function playCard(){if(state.selectedCard===null||state.selectedLane===null||state.lock||state.over||state.actionUsed)return;const card=state.hand[state.selectedCard];if(!card||card.cost>state.energy)return;state.energy-=card.cost;state.hand.splice(state.selectedCard,1);if(card.support)applyEffect(card,state.selectedLane,'player');else{state.player[state.selectedLane].push(card);applyEffect(card,state.selectedLane,'player')}state.actionUsed=true;state.selectedCard=null;state.selectedLane=null;render();showToast(`${card.emoji} ${card.name}: efecto activado`)}
function cpuPlay(){if(!state.enemyHand.length)drawCards('enemy');const options=state.enemyHand.filter(c=>c.cost<=state.energy);if(!options.length)return null;options.sort((a,b)=>(b.support?2:b.attack+b.hp/2)/b.cost-(a.support?2:a.attack+a.hp/2)/a.cost);const card=options[0];state.enemyHand.splice(state.enemyHand.indexOf(card),1);let lanes=habitats.map((_,i)=>({i,score:score(state.enemy[i])-score(state.player[i])}));lanes.sort((a,b)=>a.score-b.score);const lane=lanes[0].i;if(card.support)applyEffect(card,lane,'enemy');else{state.enemy[lane].push(card);applyEffect(card,lane,'enemy')}return card}
function combat(){for(let i=0;i<3;i++){const players=[...state.player[i]],foes=[...state.enemy[i]];if(players.length&&foes.length){const dmgToFoes=foes.map(()=>0),dmgToPlayers=players.map(()=>0);players.forEach((c,j)=>dmgToFoes[j%foes.length]+=c.attack);foes.forEach((c,j)=>dmgToPlayers[j%players.length]+=c.attack);foes.forEach((c,j)=>damageUnit(c,dmgToFoes[j]));players.forEach((c,j)=>damageUnit(c,dmgToPlayers[j]))}else if(players.length)state.enemyLife-=players.reduce((n,c)=>n+c.attack,0);else if(foes.length)state.playerLife-=foes.reduce((n,c)=>n+c.attack,0)}cleanDead();state.playerLife=Math.max(0,state.playerLife);state.enemyLife=Math.max(0,state.enemyLife)}
function endTurn(){if(state.lock||state.over)return;state.lock=true;state.selectedCard=null;state.selectedLane=null;render();setTimeout(()=>{const card=cpuPlay();combat();if(card)showToast(`Rival juega ${card.name}. ¡Combate!`);if(state.playerLife<=0||state.enemyLife<=0||state.turn>=state.maxTurns){finishGame();return}state.turn++;state.maxEnergy=Math.min(10,state.maxEnergy+1);state.energy=state.maxEnergy;state.actionUsed=false;drawCards('player');drawCards('enemy');state.lock=false;render()},500)}
function finishGame(){state.over=true;render();const won=state.playerLife>state.enemyLife,title=state.playerLife===state.enemyLife?'¡Empate salvaje!':won?'¡Victoria primigenia!':'La calamidad prevalece';const tag=state.playerLife===state.enemyLife?'EMPATE':won?'VICTORIA':'DERROTA';openModal(tag,title,`Vida final: tú ${state.playerLife} · rival ${state.enemyLife}. ${won?'Tus monstruos dominan la frontera.':'Reúne a tus criaturas y prueba otra estrategia.'}`,true,()=>newGame(),[{label:'Tu vida',value:state.playerLife},{label:'Vida rival',value:state.enemyLife},{label:'Ronda',value:Math.min(state.turn,state.maxTurns)}])}
function newGame(){state.turn=1;state.maxTurns=15;state.maxEnergy=2;state.energy=2;state.player=[[],[],[]];state.enemy=[[],[],[]];state.playerLife=30;state.enemyLife=30;state.selectedCard=null;state.selectedLane=null;state.actionUsed=false;state.over=false;state.lock=false;startDecks();closeModal();render();showToast('¡Un nuevo duelo comienza!')}
function openModal(tag,title,text,result=false,onPrimary=null,stats=[]){$('#modalTag').textContent=tag;$('#modalTitle').textContent=title;$('#modalText').textContent=text;const box=$('#resultStats');box.hidden=!result;box.innerHTML=stats.map(s=>`<div class="result-stat"><strong>${s.value}</strong><span>${s.label}</span></div>`).join('');$('#modalClose').textContent=result?'Luego':'Entendido';$('#modalPrimary').textContent=result?'Jugar de nuevo':'¡A combatir!';$('#modalBackdrop').hidden=false;$('#modalPrimary').onclick=onPrimary||closeModal}
function closeModal(){$('#modalBackdrop').hidden=true}
function help(){openModal('GUÍA DE CAMPO','Cómo jugar','Cada jugador tiene un mazo de 30 cartas. En tu turno puedes jugar 1 monstruo o una carta de ayuda y luego terminar el turno. Los monstruos tienen elemento, ataque y vida; al final de cada ronda combaten en su hábitat y el ataque sobrante daña al rival. Gasta energía con estrategia: aumenta cada ronda. Gana quien reduzca la vida rival a cero o tenga más vida al final de 15 rondas. Lee el efecto de cada carta antes de jugarla.')}
$('#arena').addEventListener('click',e=>{const lane=e.target.closest('[data-lane]');if(!lane||state.lock||state.over)return;state.selectedLane=Number(lane.dataset.lane);render()});
$('#hand').addEventListener('click',e=>{const card=e.target.closest('[data-card]');if(!card||card.disabled||state.lock||state.over||state.actionUsed)return;state.selectedCard=Number(card.dataset.card);render()});
$('#playBtn').addEventListener('click',playCard);$('#endTurnBtn').addEventListener('click',endTurn);$('#newGameBtn').addEventListener('click',newGame);$('#helpBtn').addEventListener('click',help);$('#modalClose').addEventListener('click',closeModal);$('#modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal()});
newGame();

