 function damageUnit(unit,amount){unit.hpNow-=amount}
 function applyEffect(card,lane,side){const own=state[side],other=state[side==='player'?'enemy':'player'],allies=own[lane],foe=other[lane];state[side+'Power']=card;const boost=(unit,n)=>{if(!unit)return;const before=unit.attack;unit.attack=Math.max(0,unit.attack+n);unit.tempAttack=(unit.tempAttack||0)+unit.attack-before};switch(card.effect){case'meteor':if(foe)foe.hpNow=0;break;case'lacer':if(foe)foe.hpNow-=5;break;case'warcry':boost(allies,3);break;case'surge':own.forEach(unit=>boost(unit,1));break;case'roots':if(foe)boost(foe,-2);break;case'blast':case'snipe':if(foe)foe.hpNow-=3;break;case'crush':if(foe&&foe.attack<=4)foe.hpNow=0;break;case'rally':own.forEach(unit=>boost(unit,2));break;case'overcharge':boost(allies,4);break}cleanDead()}
 function cleanDead(){for(const side of ['player','enemy'])state[side]=state[side].map(unit=>unit&&unit.hpNow>0?unit:null)}
