assert(cardPool.length===30,'deck has 30 unique cards');
assert(new Set(cardPool.map(c=>c.id)).size===30,'card ids unique');
assert(cardPool.filter(c=>c.support).length===10,'10 power cards');
assert(cardPool.filter(c=>!c.support).length===20,'20 beasts');
