const crush=cardPool.find(c=>c.id==='crush');
assert(canPlayAt(crush,'player',0),'crush may target weak enemy in lane');
assert(!canPlayAt(crush,'player',1),'crush may not target empty lane');
state.enemy[0].attack=6;assert(!canPlayAt(crush,'player',0),'crush rejects stronger enemy');
state.enemy[0].attack=3;
const warcry=cardPool.find(c=>c.id==='warcry');assert(canPlayAt(warcry,'player',0),'buff power needs ally');assert(!canPlayAt(warcry,'player',1),'buff power cannot target empty lane');
state.enemyHand=[crush];state.enemyEnergy=10;state.enemy[0].attack=6;
assert(cpuPlay()===null,'CPU must not attempt invalid power target');
assert(state.enemyHand.includes(crush),'invalid CPU card remains in hand');
state.enemy[0].attack=3;state.enemyHand=[crush];state.enemyEnergy=10;
assert(cpuPlay()===crush,'CPU plays valid target-specific power');assert(state.player[0]===null,'power resolves against correct valid target');
state.player[0]=beast('friendly');state.enemy[0]=null;
