state.player[0]=beast('survivor',3,5);state.enemy[0]=beast('enemy',2,5);
state.player[0].tempAttack=0;state.enemy[0].tempAttack=0;
combat();assert(state.player[0].hpNow===3&&state.enemy[0].hpNow===2,'combat damage is simultaneous');
console.log('PASS: setup data, card pool, power targeting, CPU targeting, effects and combat');
`;
vm.runInContext(script + tests, context);
