const assert=(ok,msg)=>{if(!ok)throw new Error(msg)};
(async()=>{
  const targets=await (await fetch('http://127.0.0.1:9222/json')).json();
  const page=targets.find(t=>t.type==='page');
  const ws=new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((resolve,reject)=>{ws.onopen=resolve;ws.onerror=reject});
  let id=0;const pending=new Map();
  ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(Error(m.error.message)):p.resolve(m.result)}};
  const cmd=(method,params={})=>new Promise((resolve,reject)=>{const n=++id;pending.set(n,{resolve,reject});ws.send(JSON.stringify({id:n,method,params}))});
  const evaluate=async expression=>{const r=await cmd('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(r.exceptionDetails)throw Error(r.exceptionDetails.text);return r.result.value};
  await cmd('Page.enable');await cmd('Runtime.enable');
  await cmd('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});
  await cmd('Page.navigate',{url:'file:///home/runner/work/PlayGround/PlayGround/index.html'});
  await new Promise(r=>setTimeout(r,500));
  assert(await evaluate(`document.querySelector('#setupTitle').textContent`)==='Elige tu mazo','deck setup visible');
  await evaluate(`document.querySelector('[data-setup="deck"]').click()`);
  assert(await evaluate(`document.querySelector('#setupTitle').textContent`)==='Elige a tu rival','rival selection follows deck');
  await evaluate(`document.querySelector('[data-setup="rival"]').click()`);
  assert((await evaluate(`document.querySelector('#setupTitle').textContent`)).includes('Quién va primero'),'first-player choice follows rival');
  await evaluate(`document.querySelector('[data-setup="first"][data-value="player"]').click()`);
  assert(await evaluate(`state.started && !document.querySelector('#setupBackdrop').hidden` )===false,'battle starts and setup closes');
