--- index.html
+++ index.html
@@ -87,9 +87,9 @@
   $('#arena').innerHTML=habitats.map((h,i)=>{const s=laneTotals(i),you=state.player[i],foe=state.enemy[i];return `<button class="lane ${state.selectedLane===i?'selected':''} ${s.foe>s.you?'enemy-lead':''} ${!you&&!foe?'empty':''}" data-lane="${i}" aria-label="Espacio ${i+1}: tu bestia ${you?.name||'vacío'}, rival ${foe?.name||'vacío'}"><div class="lane-head"><span class="lane-title">Espacio ${i+1}</span><span class="lane-icon">${h.icon}</span></div><span class="lane-score-row">TÚ / RIVAL · ATQ</span><span class="lane-score">${s.you}<small style="font:500 10px var(--sans);color:#829078"> / ${s.foe}</small></span><div class="lane-art"><span>${you?.emoji||foe?.emoji||h.art}</span></div><div class="beast-name">${you?.name||'Vacío'}${foe?` · ${foe.emoji} ${foe.name}`:''}</div></button>`}).join('')+`<div class="power-row"><div class="power-slot"><strong>PODER · TÚ</strong> ${state.playerPower?`${state.playerPower.emoji} ${state.playerPower.name}`:'Vacío'}</div><div class="power-slot foe"><strong>PODER · RIVAL</strong> ${state.enemyPower?`${state.enemyPower.emoji} ${state.enemyPower.name}`:'Vacío'}</div></div>`;
  $('#energyPips').innerHTML=Array.from({length:state.maxEnergy},(_,i)=>`<span class="pip ${i<state.energy?'on':''}"></span>`).join('');$('#energyText').textContent=`${state.energy} / ${state.maxEnergy}`;
  $('#handCount').textContent=`${state.hand.length} ${state.hand.length===1?'carta':'cartas'}`;
   $('#hand').innerHTML=state.hand.map((c,i)=>`<button class="card ${state.selectedCard===i?'selected':''}" data-card="${i}" style="--accent:${c.color}" ${c.cost>state.energy||state.lock||state.over||state.actionUsed||!state.started||!hasValidSlot(c,'player')?'disabled':''} aria-label="${c.name}, ${c.support?'carta de poder':`ataque ${c.attack}, vida ${c.hp}`}, cuesta ${c.cost} de energía"><div class="card-top"><span class="faction">${c.faction}</span><span class="cost">${c.cost}</span></div><div class="card-art">${c.emoji}</div><div class="card-name">${c.name}</div><div class="card-desc">${c.desc}</div><div class="card-bottom"><span class="card-type">${c.support?'Poder':c.faction+' · '+c.type}</span><span class="power">${c.support?'✦':`${c.attack}<small style="font:700 7px var(--sans)"> ATQ</small><br>${c.hp}<small style="font:700 7px var(--sans)"> VIDA</small>`}</span></div></button>`).join('');
- const status=$('#turnStatus');status.innerHTML=!state.started?'<strong>Duelo sin iniciar.</strong> Completa la preparación.':state.over?'<strong>Partida terminada.</strong> La naturaleza ha decidido.':state.lock?'<strong>Turno del rival…</strong>':state.actionUsed?'<strong>Acción realizada.</strong> Termina tu turno para combatir.':`<strong>Tu turno.</strong> ${state.selectedCard!==null?'Elige un hábitat para jugar.':'Juega una carta o termina el turno.'}`;
+ $('#turnMessage').innerHTML=!state.started?'<strong>Duelo sin iniciar.</strong> Completa la preparación.':state.over?'<strong>Partida terminada.</strong> La naturaleza ha decidido.':state.lock?'<strong>Turno del rival…</strong>':state.actionUsed?'<strong>Acción realizada.</strong> Termina tu turno para combatir.':`<strong>Tu turno.</strong> ${state.selectedCard!==null?'Elige un hábitat para jugar.':'Juega una carta o termina el turno.'}`;
  $('#selectionHelp').innerHTML=state.selectedCard===null?'Elige una carta y un hábitat. Puedes jugar 1 carta por turno.':`<b>${state.hand[state.selectedCard]?.name||'Carta'}</b> seleccionada · elige un hábitat`;
  $('#playBtn').disabled=state.selectedCard===null||state.selectedLane===null||state.lock||state.over||state.actionUsed||!state.started;
  $('#endTurnBtn').disabled=state.lock||state.over||!state.started;
  $('#newGameBtn').disabled=state.lock;

